"use client";

import React, { useState, useCallback, useEffect, useRef } from 'react';
import ReactFlow, {
  ReactFlowProvider,
  useNodesState,
  useEdgesState,
  addEdge,
  MiniMap,
  Controls,
  Background,
  type Connection,
  type Edge,
  type Node,
  BackgroundVariant,
  type EdgeMarkerType,
  type NodeChange,
  type EdgeChange,
  applyNodeChanges,
  applyEdgeChanges,
  useReactFlow,
} from 'reactflow';
import 'reactflow/dist/style.css';
import { doc, getDoc, setDoc } from 'firebase/firestore';

import { db, isFirebaseConfigured } from '@/lib/firebase/client';
import { useAuth } from '@/hooks/use-auth';
import TaskNode, { type TaskData } from '@/components/task-node';
import TitleNode, { type TitleData } from '@/components/title-node';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/hooks/use-toast';
import { suggestTaskConnections } from '@/ai/flows/suggest-task-connections';
import { Plus, Sparkles, Loader2, Type } from 'lucide-react';
import { UserMenu } from './user-menu';

const nodeTypes = {
  task: TaskNode as React.FC<any>,
  title: TitleNode as React.FC<any>,
};

const initialNodes: Node[] = [
  {
    id: 'task-1',
    type: 'task',
    position: { x: 100, y: 100 },
    data: { title: 'Project Kick-off', description: 'Double-click me to edit my content!', status: 'done' },
  },
  {
    id: 'task-2',
    type: 'task',
    position: { x: 400, y: 50 },
    data: { title: 'Design Phase', description: 'Create wireframes and mockups.', status: 'inprogress' },
  },
  {
    id: 'task-3',
    type: 'task',
    position: { x: 400, y: 200 },
    data: { title: 'Development', description: 'Use the "Add Task" button to create new tasks.', status: 'todo' },
  },
];

const initialEdges: Edge[] = [
    { id: 'e1-2', source: 'task-1', target: 'task-2' },
];

const defaultEdgeOptions = {
    animated: true,
    type: 'smoothstep',
    style: { strokeWidth: 2 },
    markerEnd: { type: 'arrowclosed' as EdgeMarkerType },
  };

function MindMapComponent() {
  const [nodes, setNodes] = useState<Node<any>[]>([]);
  const [edges, setEdges] = useState<Edge[]>(initialEdges);
  const [isAiDialogOpen, setAiDialogOpen] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isDataLoaded, setIsDataLoaded] = useState(false);
  const { toast } = useToast();
  const { user } = useAuth();
  const { deleteElements } = useReactFlow();
  
  const nodesRef = useRef(nodes);
  const edgesRef = useRef(edges);

  useEffect(() => {
    nodesRef.current = nodes;
    edgesRef.current = edges;
  }, [nodes, edges]);

  const saveData = useCallback(async (nodesToSave: Node[], edgesToSave: Edge[]) => {
    if (!user || !isFirebaseConfigured || !db) return;
    try {
      const plainNodes = nodesToSave.map(({ data, ...node }) => {
        const { onUpdateNode, onDeleteNode, ...restData } = data;
        return { ...node, data: restData };
      });
      const userDocRef = doc(db, 'mindmaps', user.uid);
      await setDoc(userDocRef, { nodes: plainNodes, edges: edgesToSave });
    } catch (error) {
      console.error('Error saving data:', error);
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Failed to save your mind map.',
      });
    }
  }, [user, toast]);

  const onUpdateNode = useCallback((id: string, data: Record<string, any>) => {
    const newNodes = nodesRef.current.map((node) => {
      if (node.id === id) {
        return { ...node, data: { ...node.data, ...data } };
      }
      return node;
    });
    setNodes(newNodes);
    saveData(newNodes, edgesRef.current);
  }, [saveData]);

  const onDeleteNode = useCallback((nodeId: string) => {
    const nodeToRemove = nodesRef.current.find(n => n.id === nodeId);
    deleteElements({ nodes: [{ id: nodeId }] });
    if (nodeToRemove) {
      toast({
        title: 'Node Removed',
        description: `"${nodeToRemove.data.title || nodeToRemove.data.label}" was deleted.`,
      });
    }
  }, [deleteElements, toast]);


  useEffect(() => {
    const loadInitialData = () => {
      const nodesWithCallback: Node<any>[] = initialNodes.map((node) => ({
        ...node,
        data: { ...node.data, onUpdateNode, onDeleteNode },
      }));
      setNodes(nodesWithCallback);
      setEdges(initialEdges);
      setIsDataLoaded(true);
    };

    if (!user || !isFirebaseConfigured || !db) {
      loadInitialData();
      return;
    }

    const loadData = async () => {
      setIsDataLoaded(false);
      const userDocRef = doc(db, 'mindmaps', user.uid);
      const docSnap = await getDoc(userDocRef);

      if (docSnap.exists()) {
        const data = docSnap.data();
        const loadedNodes: Node<any>[] = (data.nodes || []).map((node: Node) => ({
          ...node,
          data: {
            ...node.data,
            onUpdateNode,
            onDeleteNode,
          },
        }));
        setNodes(loadedNodes);
        setEdges(data.edges || []);
      } else {
        const nodesWithCallback: Node<any>[] = initialNodes.map((node) => ({
          ...node,
          data: { ...node.data, onUpdateNode, onDeleteNode },
        }));
        setNodes(nodesWithCallback);
        setEdges(initialEdges);
        saveData(nodesWithCallback, initialEdges);
      }
      setIsDataLoaded(true);
    };

    loadData();
  }, [user, onUpdateNode, onDeleteNode, saveData]);


  const onNodesChange = useCallback((changes: NodeChange[]) => {
      const newNodes = applyNodeChanges(changes, nodesRef.current);
      setNodes(newNodes);
      if (changes.some(c => c.type === 'remove' || c.type === 'position' && c.dragging === false)) {
          saveData(newNodes, edgesRef.current);
      }
  }, [saveData]);

  const onEdgesChange = useCallback((changes: EdgeChange[]) => {
      const newEdges = applyEdgeChanges(changes, edgesRef.current);
      setEdges(newEdges);
      if (changes.some(c => c.type === 'remove')) {
          saveData(nodesRef.current, newEdges);
      }
  }, [saveData]);
  
  const onConnect = useCallback((params: Connection) => {
    const newEdges = addEdge(params, edgesRef.current);
    setEdges(newEdges);
    saveData(nodesRef.current, newEdges);
  }, [saveData]);

  const handleAddTask = useCallback(() => {
    const id = `task-${crypto.randomUUID()}`;
    const newNode: Node<TaskData> = {
      id,
      type: 'task',
      position: {
        x: Math.random() * 500,
        y: Math.random() * 500,
      },
      data: {
        title: 'New Task',
        description: '',
        status: 'todo',
        onUpdateNode,
        onDeleteNode,
      },
    };
    const newNodes = nodesRef.current.concat(newNode);
    setNodes(newNodes);
    saveData(newNodes, edgesRef.current);
  }, [onUpdateNode, onDeleteNode, saveData]);

  const handleAddTitle = useCallback(() => {
    const id = `title-${crypto.randomUUID()}`;
    const newNode: Node<TitleData> = {
      id,
      type: 'title',
      position: {
        x: Math.random() * 200,
        y: Math.random() * 200,
      },
      data: {
        label: 'Floating Title',
        fontSize: 28,
        onUpdateNode,
        onDeleteNode,
      },
    };
    const newNodes = nodesRef.current.concat(newNode);
    setNodes(newNodes);
    saveData(newNodes, edgesRef.current);
  }, [onUpdateNode, onDeleteNode, saveData]);

  const handleOpenAiDialog = useCallback(() => {
    const prompt = `Here is a list of tasks and titles. Each item has an ID and content.\n\n${nodes
      .map((node) => {
        if (node.type === 'task') {
            return `- ID: ${node.id}, Type: Task, Title: ${node.data.title}, Description: ${node.data.description}`
        }
        if (node.type === 'title') {
            return `- ID: ${node.id}, Type: Title, Text: ${node.data.label}`
        }
        return '';
      })
      .filter(Boolean)
      .join('\n')}\n\nPlease suggest logical connections (dependencies, workflows, groupings) between these items. The source and target should be the item IDs.`;
    setAiPrompt(prompt);
    setAiDialogOpen(true);
  }, [nodes]);

  const handleSuggestConnections = useCallback(async () => {
    setIsLoading(true);
    try {
      const result = await suggestTaskConnections({ prompt: aiPrompt });
      const newEdges = result.connections.map((conn) => ({
        id: `e-${conn.source}-${conn.target}-${crypto.randomUUID()}`,
        source: conn.source,
        target: conn.target,
        label: conn.label,
        ...defaultEdgeOptions
      }));

      const existingEdgeSet = new Set(edgesRef.current.map(e => `${e.source}-${e.target}`));
      const filteredNewEdges = newEdges.filter(ne => !existingEdgeSet.has(`${ne.source}-${ne.target}`));

      if(filteredNewEdges.length === 0 && newEdges.length > 0) {
        toast({
            title: "AI Suggestion",
            description: "AI suggested connections that already exist.",
        });
      }
      
      const allEdges = edgesRef.current.concat(filteredNewEdges);
      setEdges(allEdges);
      saveData(nodesRef.current, allEdges);
      setAiDialogOpen(false);
    } catch (error) {
      console.error('AI suggestion failed:', error);
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Failed to get AI suggestions. Please try again.',
      });
    } finally {
      setIsLoading(false);
    }
  }, [aiPrompt, toast, saveData]);

  if (!isDataLoaded) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-background text-foreground">
      <header className="flex items-center justify-between p-4 border-b shrink-0">
        <h1 className="text-xl font-bold md:text-2xl font-headline text-foreground">MindTask Navigator</h1>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Button onClick={handleAddTitle} size="sm" variant="outline">
              <Type className="mr-2" />
              Add Title
            </Button>
            <Button onClick={handleAddTask} size="sm" variant="outline">
              <Plus className="mr-2" />
              Add Task
            </Button>
            <Button onClick={handleOpenAiDialog} size="sm">
              <Sparkles className="mr-2" />
              AI Suggest
            </Button>
          </div>
          <UserMenu />
        </div>
      </header>
      <main className="flex-1">
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          nodeTypes={nodeTypes}
          defaultEdgeOptions={defaultEdgeOptions}
          fitView
          className="bg-background"
        >
          <Controls />
          <MiniMap nodeStrokeWidth={3} zoomable pannable />
          <Background variant={BackgroundVariant.Dots} gap={16} />
        </ReactFlow>
      </main>
      <Dialog open={isAiDialogOpen} onOpenChange={setAiDialogOpen}>
        <DialogContent className="sm:max-w-[625px]">
          <DialogHeader>
            <DialogTitle>AI-Powered Connection Suggestions</DialogTitle>
            <DialogDescription>
              Review and edit the prompt below. The AI will suggest connections based on your tasks.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <Textarea
              value={aiPrompt}
              onChange={(e) => setAiPrompt(e.target.value)}
              className="min-h-[200px]"
              placeholder="Provide a prompt for the AI..."
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAiDialogOpen(false)} disabled={isLoading}>Cancel</Button>
            <Button onClick={handleSuggestConnections} disabled={isLoading}>
              {isLoading ? <Loader2 className="animate-spin mr-2" /> : <Sparkles className="mr-2" />}
              Generate
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}


export default function MindMap() {
  return (
    <ReactFlowProvider>
      <MindMapComponent />
    </ReactFlowProvider>
  );
}
